style.css:
@-moz-document domain("regama.xyz") {
body {
        /* Укажите прямую ссылку на картинку вместо URL_КАРТИНКИ */
        background-image: url("https://cdn-www.bluestacks.com/bs-images/featured_com.multiverse.kogama.jpg") !important;
        
        /* Настройки отображения фона */
        background-size: cover !important;       /* Растягивает фото на весь экран */
        background-attachment: fixed !important;  /* Фон не прокручивается вместе со страницей */
        background-position: center !important;  /* Центрирует изображение */
        background-repeat: no-repeat !important;  /* Запрещает дублирование картинки */
    }
}
